  ('Sara De Masi', null, '#f2b35b', '#f2b35b', 'dark', 'sara.demasi@unifi.it', null, 'Sara De Masi — Corporate Governance & Board Diversity | University of Florence', 'Sara De Masi is Associate Professor of Management at the University of Florence. Research on corporate governance, board diversity, women on boards, ESG and executive compensation.', 'Associate Professor of Management, University of Florence', 'Invite Me', '[{"key":"about","visible":true},{"key":"publications","visible":true},{"key":"teaching","visible":true},{"key":"blog","visible":true},{"key":"cv","visible":true},{"key":"contact","visible":true}]'::jsonb, null, true);
insert into public.profile (full_name, professional_title, typed_roles, short_intro, bio, email, phone, location, profile_image_url, hero_image_url, hero_headline, hero_background_url, resume_url, availability_status, trust_line, about_title, about_image_url, about_points, experience_years, work_photos, personal_info, social_links, skill_tools, affiliation, research_interests, press_bio, cv_updated) values
  ('Sara De Masi', 'Associate Professor of Management', array['Associate Professor', 'Corporate Governance Scholar', 'Board Diversity Researcher', 'Executive Educator']::text[], 'Associate Professor of Management at the University of Florence. Research on corporate governance, board diversity, women on boards, executive compensation and ESG.', 'Sara De Masi is Associate Professor of Management at the University of Florence, Department of Economics and Management, where she also serves on the International Relations Committee. She is an internationally engaged scholar with extensive experience in research, executive education, and global academic collaborations.
insert into public.services (title, short_description, icon_key, active, sort_order) values
  ('Corporate governance & boards', 'How boards of directors are composed, how they monitor and advise, and how governance shapes strategy and performance.', 'landmark', true, 1),
  ('Gender diversity & women on boards', 'The effects of women directors, critical mass, board chairs and quotas on board dynamics, tasks and corporate outcomes.', 'users', true, 2),
  ('Executive compensation & incentives', 'CEO pay design, incentives and disclosure, in listed firms, banks and regulated industries.', 'coins', true, 3),
  ('ESG & sustainability', 'How board composition and leadership drive environmental, social and governance performance and disclosure.', 'leaf', true, 4),
  ('Regulated & public-utility firms', 'Governance and incentives in energy, telecom and other regulated companies, and in banks.', 'factory', true, 5),
  ('Academic entrepreneurship & technology transfer', 'Organisational change inside entrepreneurial and engaged universities.', 'graduation', true, 6);
