insert into public.blog_posts (title, slug, excerpt, content, cover_image_url, category, read_time, published_at, link_url, status) values
  ('Presenting new research on chairwomen at ICGS 2026', 'icgs-2026-chairwomen-pathways', 'At HEC Montréal, new work on how women reach the chair of the board in France, Spain and Italy.', 'Sara De Masi presented new research on chairwomen and the pathways to board leadership in France, Spain and Italy at the 12th Annual Conference of the International Corporate Governance Society (ICGS), held at HEC Montréal on 2–4 October 2026.
